import { Option } from 'models/Filters';

function optionValueMatchesOption(opt: Option, value: unknown): boolean {
  if (opt.value === value) {
    return true;
  }
  if (typeof value === 'string' || typeof value === 'number') {
    return String(opt.value) === value;
  }
  if (typeof value === 'boolean' || typeof value === 'bigint') {
    return String(opt.value) === String(value);
  }
  return false;
}

/**
 * Whether `value` matches an option in `options` (strict or string-coerced for primitives).
 */
export function isFilterSelectValueInOptions(
  options: Option[],
  value: unknown,
): boolean {
  if (value == null || value === '') {
    return false;
  }
  if (
    typeof value === 'object' ||
    typeof value === 'symbol' ||
    typeof value === 'function'
  ) {
    return false;
  }
  return options.some((opt) => optionValueMatchesOption(opt, value));
}

function primitiveUnknownToDisplayString(value: unknown): string {
  if (typeof value === 'string') {
    return value;
  }
  if (
    typeof value === 'number' ||
    typeof value === 'boolean' ||
    typeof value === 'bigint'
  ) {
    return String(value);
  }
  return '';
}

/**
 * Select `value` for react-select: prefer form when valid in list, else registry default when
 * valid, else first option (keeps UI aligned with `selectPageDefaults` / API defaults).
 */
export function resolveFilterSelectDisplayValue(
  options: Option[],
  formValue: unknown,
  defaultFromRegistry: unknown,
  fallbackToFirst = true,
): string {
  if (isFilterSelectValueInOptions(options, formValue)) {
    return primitiveUnknownToDisplayString(formValue);
  }
  if (isFilterSelectValueInOptions(options, defaultFromRegistry)) {
    return primitiveUnknownToDisplayString(defaultFromRegistry);
  }
  return fallbackToFirst ? String(options[0]?.value ?? '') : '';
}
